import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { discoverInventory, sourceHash } from '../scripts/quality-inventory';
const inputs=discoverInventory(process.cwd()).files.map(f=>({path:f.path,sourceHash:f.sourceHash}));
const runs=[];
for(const command of [[process.execPath,'run','typecheck'],[process.execPath,resolve('node_modules/typescript/bin/tsc'),'--project','.git/q100-maintenance-tests-tsconfig.json'],[process.execPath,'run','test:isolation']]){
 const startedAt=new Date().toISOString(),r=Bun.spawnSync(command,{stdout:'pipe',stderr:'pipe',timeout:120000});
 runs.push({command,startedAt,finishedAt:new Date().toISOString(),exit:r.exitCode,output:new TextDecoder().decode(r.stdout)+new TextDecoder().decode(r.stderr)});
}
for(const file of inputs)if(sourceHash(readFileSync(file.path,'utf8'))!==file.sourceHash)throw Error('Input changed '+file.path);
writeFileSync('.git/q100-maintenance-checks.json',JSON.stringify({recordedAt:new Date().toISOString(),sourceInputs:inputs,runs,source:readFileSync(import.meta.path,'utf8')},null,2)+'\n');
console.log(JSON.stringify(runs));if(runs.some(r=>r.exit!==0))throw Error('Checks failed');
